referenceSolutions.python:
def sortingPressPeakTicket(readings, k):
    a=readings
    out=[]
    def sort(xs):
        if len(xs)<2: return xs
        mid=len(xs)//2
        left,right=sort(xs[:mid]),sort(xs[mid:])
        merged=[]
        i=j=0
        while i<len(left) or j<len(right):
            if j==len(right) or (i<len(left) and left[i]<=right[j]):
                merged.append(left[i])
                i+=1
            else:
                merged.append(right[j])
                j+=1
        return merged
    out=sort(a[:])
    return max(out,default=0)

referenceSolutions.java:
class Solution {
  public int sortingPressPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {class Sorter {int[]sort(int[]xs){if(xs.length<2)return xs;int m=xs.length/2;int[]left=sort(Arrays.copyOfRange(xs,0,m)),right=sort(Arrays.copyOfRange(xs,m,xs.length)),merged=new int[xs.length];int i=0,j=0,t=0;while(i<left.length||j<right.length)merged[t++]=j==right.length||(i<left.length&&left[i]<=right[j])?left[i++]:right[j++];return merged;}}for(int x:new Sorter().sort(a.clone()))out.add(x);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}

